mapper.select:
select 
from text_to_sql_eval_run_result

    eval_run_id = #{evalRunId}

        and passed = #{passed}


        and failure_type = #{failureType}


        and (
            question like concat('%', #{keyword}, '%')
            or failure_reason like concat('%', #{keyword}, '%')
            or actual_answer like concat('%', #{keyword}, '%')
        )


order by id asc
